CREATE TABLE "editors" (
  "editor_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "editor_login" varchar UNIQUE NOT NULL,
  "editor_name_last" varchar,
  "editor_name_first" varchar,
  "permissions" integer,
  "created_at" timestamp DEFAULT (now())
);

CREATE TABLE "games" (
  "gidb_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "mobygames_id" integer UNIQUE,
  "igdb_id" integer UNIQUE,
  "steam_id" integer UNIQUE,
  "gog_id" integer UNIQUE,
  "itch_id" varchar UNIQUE,
  "wikidata_id" varchar UNIQUE,
  "game_title" text NOT NULL,
  "game_parent_id" integer,
  "game_year" integer,
  "game_url" varchar,
  "gidb_status" varchar,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp DEFAULT (now()),
  "modified_at" timestamp DEFAULT (now()),
  CHECK (game_parent_id <> gidb_id)
);

CREATE TABLE "collections" (
  "collection_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "collection_name" varchar UNIQUE NOT NULL,
  "collection_description" text,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp DEFAULT (now()),
  "modified_at" timestamp DEFAULT (now())
);

CREATE TABLE "games_collections_map" (
  "gidb_id" integer,
  "collection_id" integer,
  PRIMARY KEY ("gidb_id", "collection_id")
);

CREATE TABLE "categories" (
  "category_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "category_name" varchar UNIQUE NOT NULL,
  "category_source" varchar
);

CREATE TABLE "tags" (
  "tag_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tag_name" varchar UNIQUE NOT NULL,
  "category_id" integer
);

CREATE TABLE "games_tags_map" (
  "gidb_id" integer,
  "tag_id" integer,
  PRIMARY KEY ("gidb_id", "tag_id")
);

CREATE TABLE "originator_roles" (
  "originator_role_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "originator_role_name" varchar UNIQUE NOT NULL
);

CREATE TABLE "originators" (
  "originator_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "originator_mobygames_id" integer UNIQUE,
  "originator_igdb_id" integer UNIQUE,
  "originator_wikidata_id" varchar UNIQUE,
  "originator_name" varchar NOT NULL,
  "originator_description" text,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp DEFAULT (now()),
  "modified_at" timestamp DEFAULT (now())
);

CREATE TABLE "games_originators_map" (
  "originator_id" integer,
  "gidb_id" integer,
  "originator_role" integer,
  PRIMARY KEY ("originator_id", "gidb_id", "originator_role")
);

CREATE TABLE "originators_locations_map" (
  "originator_id" integer,
  "location_id" integer,
  PRIMARY KEY ("originator_id", "location_id")
);

CREATE TABLE "notes" (
  "note_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "note" text NOT NULL,
  "gidb_id" integer,
  "source_id" integer,
  "representation_id" integer,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp DEFAULT (now()),
  "modified_at" timestamp DEFAULT (now()),
  CHECK (num_nonnulls(gidb_id, source_id, representation_id) = 1)
);

CREATE TABLE "countries" (
  "country_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "geonames_id" integer UNIQUE,
  "country_code" varchar UNIQUE NOT NULL,
  "country_name" varchar UNIQUE NOT NULL
);

CREATE TABLE "locations" (
  "location_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "geonames_id" integer UNIQUE,
  "wikidata_id" varchar UNIQUE,
  "is_fictional" bool NOT NULL DEFAULT false,
  "latitude" decimal,
  "longitude" decimal,
  "location_name" varchar NOT NULL,
  "country_id" integer,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp DEFAULT (now()),
  "modified_at" timestamp DEFAULT (now()),
  CHECK ((latitude IS NULL) = (longitude IS NULL)),
  CHECK (latitude BETWEEN -90 AND 90),
  CHECK (longitude BETWEEN -180 AND 180)
);

CREATE TABLE "attachments" (
  "attachment_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "gidb_id" integer,
  "sign_id" integer,
  "source_id" integer,
  "attachment_path" varchar NOT NULL,
  "attachment_filename" varchar,
  "attachment_mime" varchar,
  "attachment_type" varchar,
  "attachment_provenance" varchar,
  "attachment_license" varchar,
  "attachment_publishable" boolean NOT NULL DEFAULT false,
  "attachment_description" text,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp DEFAULT (now()),
  "modified_at" timestamp DEFAULT (now()),
  CHECK (num_nonnulls(gidb_id, sign_id, source_id) = 1)
);

CREATE TABLE "signs" (
  "sign_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "gidb_id" integer NOT NULL,
  "sign_name" varchar NOT NULL,
  "description" text,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp DEFAULT (now()),
  "modified_at" timestamp DEFAULT (now())
);

CREATE TABLE "sources" (
  "source_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sign_id" integer NOT NULL,
  "location_id" integer NOT NULL,
  "technology" varchar,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp DEFAULT (now()),
  "modified_at" timestamp DEFAULT (now())
);

CREATE TABLE "representations" (
  "representation_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sign_id" integer NOT NULL,
  "location_id" integer NOT NULL,
  "is_direct" bool NOT NULL DEFAULT false,
  "period_id" integer,
  "created_by" integer,
  "modified_by" integer,
  "created_at" timestamp DEFAULT (now()),
  "modified_at" timestamp DEFAULT (now())
);

CREATE TABLE "periods" (
  "period_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "period_name" varchar UNIQUE,
  "year_from" integer,
  "year_to" integer,
  "wikidata_id" varchar UNIQUE,
  CHECK (year_from <= year_to)
);

